const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
let count1 = 0;
let count2 = 0;

for (let i = 1; i <= n; i++) {
  if (data[i] === 1) count1++;
  else count2++;
}

const p = data[n + 1];
const m = data[n + 2];

console.log(count1 <= p && count2 <= m ? 'S' : 'N');
